        String(localized: "Images at http(s) links: skip doesn't show them, download fetches them and keeps them until orgstar quits, cache keeps them on disk.", comment: "Help for a config.toml setting"),
        String(localized: "Line numbers in the editor's gutter: false for none, true for each line's number, \"relative\" for how many lines of the file away from the caret's line, \"visual\" for how many lines on the screen away, counting each wrapped line. View ▸ Line Numbers changes it. The iOS editor has no line numbers.", comment: "Help for a config.toml setting"),
        String(localized: "Long lines run off the right edge instead of wrapping. Emacs's default is t; Doom Emacs wraps.", comment: "Help for a config.toml setting"),
        String(localized: "Milliseconds after typing stops before the completion list opens by itself. Emacs's corfu-auto-delay is in seconds.", comment: "Help for a config.toml setting"),
        String(localized: "Minutes of warning before timed entries. An entry's APPT_WARNTIME property overrides it.", comment: "Help for a config.toml setting"),
        String(localized: "Minutes without keyboard or mouse input, with a clock running, before orgstar asks what to do with the idle time. 0 never asks (Emacs's nil). Mac only.", comment: "Help for a config.toml setting"),
        String(localized: "Show habits only on today's agenda. Off, a habit also shows on the later days it is scheduled for.", comment: "Help for a config.toml setting"),
        String(localized: "Tags that never inherit, separated by spaces, such as crypt. As in Org, it applies when org-use-tag-inheritance is t or a regular expression, not a list of names. Read at launch.", comment: "Help for a config.toml setting"),
        String(localized: "Text search snippets match whole words only, as a leading : does.", comment: "Help for a config.toml setting"),
        String(localized: "The TODO keywords of files without a #+TODO line, in #+TODO syntax: active keywords, then |, then done keywords, such as \"TODO NEXT | DONE\". Separate several sequences with \\n. A letter in parentheses after a keyword, as in TODO(t), turns on fast selection with that key. Read at launch.", comment: "Help for a config.toml setting"),
        String(localized: "The TODO list leaves out entries with deadlines: \"near\" (or \"t\") those within their warning period, \"far\" those beyond it, \"all\", \"future\", \"past\", \"N\" or \"-N\" as for scheduled entries; \"nil\" none.", comment: "Help for a config.toml setting"),
        String(localized: "The TODO list leaves out entries with other active timestamps: \"all\" (or \"t\"), \"future\", \"past\", \"N\" or \"-N\" as for scheduled entries; \"nil\" none.", comment: "Help for a config.toml setting"),
        String(localized: "The TODO list leaves out scheduled entries: \"all\" (or \"t\") all of them, \"future\" those scheduled after today, \"past\" today or before, \"N\" N or more days ahead, \"-N\" N or more days ago; \"nil\" none.", comment: "Help for a config.toml setting"),
        String(localized: "The agenda's first day relative to today, as \"-3d\" or \"+0d\". Only day offsets are accepted.", comment: "Help for a config.toml setting"),
        String(localized: "The capture template Capture to Daily Note files under, in capture template syntax: %? is where the caret goes.", comment: "Help for a config.toml setting"),
        String(localized: "The column Fill Paragraph (M-q) breaks lines at, and the column past which typing a space breaks the line when auto-fill-mode is on.", comment: "Help for a config.toml setting"),
        String(localized: "The day weeks start on, 0 (Sunday) to 6 (Saturday), for the week view and spans of 7 or 14 days. nil starts them on the day the view starts from.", comment: "Help for a config.toml setting"),
        String(localized: "The entries that are projects, as a tag and property match: \"+LEVEL=2/-DONE\" is every level-2 heading that isn't DONE. A project is stuck when nothing in it matches the other three.", comment: "Help for a config.toml setting"),
        String(localized: "The file flashcard ratings are added to, in org-fc's format: relative to the configuration folder unless absolute, ~ for your home folder; empty for org-fc-reviews.tsv in the configuration folder.", comment: "Help for a config.toml setting"),
        String(localized: "The key preset: emacs, mac or doom. Bindings of your own in keymap.toml go over it.", comment: "Help for a config.toml setting"),
        String(localized: "The key, in capture.toml, of the template the menu bar's capture field files with when Return is pressed. A template with prompts opens the capture window instead. \"\" uses the first template.", comment: "Help for a config.toml setting"),
        String(localized: "The org-agenda-todo-ignore settings apply to TODO-only tag matches (M) too, not only to the TODO list.", comment: "Help for a config.toml setting"),
        String(localized: "The prefix of lines in the TODO list, with the codes of the day view's.", comment: "Help for a config.toml setting"),
        String(localized: "The prefix of lines in the day view: %c the category, %t the time, %s the scheduled or deadline leader, %e the effort, %l the level, %b the outline path; a width after %, as in %-12:c, pads the item. A view in views.toml can set its own with prefix-format.", comment: "Help for a config.toml setting"),
        String(localized: "The prefix of tag and property match lines, with the codes of the day view's.", comment: "Help for a config.toml setting"),
        String(localized: "The tags Set Tags (C-c C-q) offers in files without #+TAGS, in #+TAGS syntax: a letter in parentheses is the tag's key, and tags in braces exclude each other, as in \"work(w) home(h) { @office(o) @home(H) }\". Separate rows with \\n.", comment: "Help for a config.toml setting"),
        String(localized: "The text size, in points. Headings are larger by heading-size-step per level. On iOS it is the size at the default text size and grows and shrinks with Dynamic Type.", comment: "Help for a config.toml setting"),
        String(localized: "Typing an opening bracket, < or a quote also types its closing one, as electric-pair-mode does. Off in plain Emacs; Doom Emacs pairs with smartparens.", comment: "Help for a config.toml setting"),
        String(localized: "What a SCHEDULED date makes in iCalendar export, separated by spaces: event-if-not-todo, event-if-todo, event-if-todo-not-done and todo-start.", comment: "Help for a config.toml setting"),
        String(localized: "What marking an entry done records: nil records nothing, time adds a CLOSED timestamp, note adds the timestamp and asks for a note.", comment: "Help for a config.toml setting"),
        String(localized: "What the Mac menu bar item shows beside the clock symbol while a clock runs. heading: the time and the heading, as Org's mode line shows them, such as [0:25] (Write the report), with the entry's clocked total and its Effort when it has one; time: the time since clocking in, such as 0:25; none: the symbol only.", comment: "Help for a config.toml setting"),
        String(localized: "Where Archive Subtree moves an entry that has no ARCHIVE property and whose file has no #+ARCHIVE: line, as file::heading. %s is the file's name, so \"%s_archive::\" moves entries of notes.org to the top level of notes.org_archive.", comment: "Help for a config.toml setting"),
        String(localized: "Where clock lines go: \"t\" the log drawer (LOGBOOK), \"nil\" no drawer, \"N\" a drawer once there are N clock lines, or a drawer's name. An entry's CLOCK_INTO_DRAWER property overrides it.", comment: "Help for a config.toml setting"),
        String(localized: "Where state change notes go: a drawer's name, such as \"LOGBOOK\" (Emacs's t), or \"\" to put them under the heading.", comment: "Help for a config.toml setting"),
        String(localized: "Whether an entry's attachment folder can come from an ancestor's DIR or ID property: selective follows org-use-property-inheritance, t always, nil never.", comment: "Help for a config.toml setting"),
        String(localized: "Which Option key is Meta in the editor: left, right, both or none.", comment: "Help for a config.toml setting"),
        String(localized: "Which days get a grid, separated by spaces: daily (views of one day), today, weekly (every day), require-timed (only days with a timed entry) and remove-match (no line at a time an entry has).", comment: "Help for a config.toml setting"),
        String(localized: "Which properties a heading takes from its ancestors: nil for none, t for all, or the names of the properties that inherit, separated by spaces, such as \"STYLE\". ID and CUSTOM_ID never inherit.", comment: "Help for a config.toml setting"),
        String(localized: "Which tags a heading takes from its ancestors: \"t\" all, \"nil\" none, tag names separated by spaces, or a regular expression in braces, such as \"{^@}\" for the tags that start with @. Read at launch.", comment: "Help for a config.toml setting"),
        String(localized: "While markup is hidden, entities such as \\alpha show as the character they name (α), and subscripts and superscripts such as x_{1} are drawn lowered or raised.", comment: "Help for a config.toml setting"),
        String(localized: "While markup is hidden, the markers around *bold*, /italic/, =code= and the other emphasis are hidden, and tags, tables and filling measure the text without them. View ▸ Show Markup shows them.", comment: "Help for a config.toml setting"),
        String(localized: "t dims entries that org-enforce-todo-dependencies or org-enforce-todo-checkbox-dependencies blocks, invisible hides them (entries blocked only by checkboxes are still dimmed), nil shows them as usual.", comment: "Help for a config.toml setting"),
        String(localized: "t or confirm: a refile target typed as an existing target, /, and a new heading's title adds that heading under the target; confirm asks first. nil doesn't.", comment: "Help for a config.toml setting"),
        String(localized: "⌃⌥Space opens Capture from any app on the Mac. Templates go in capture.toml.", comment: "Help for a config.toml setting"),
    ]
}
